def parse_requirement(line):
    line = line.replace(' ', '')
    if not line or line.startswith('#'):
        return None
    for op in ('~=', '>=', '<=', '==', '>', '<'):
        if op in line:
            name, version = line.split(op, 1)
            return (name.lower(), op, version)

def missing_packages(requirements_text, installed):
    required = set()
    for line in requirements_text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        required.add(line.split('==')[0].lower())
    have = {name.lower() for name in installed}
    return sorted(required - have)

