def as_tuple(v):
    return tuple(int(p) for p in v.split('.'))

def satisfies(installed, rule):
    for op in ('~=', '==', '>=', '<'):
        if rule.startswith(op):
            i, w = as_tuple(installed), as_tuple(rule[len(op):])
            break
    if op == '~=':
        return i >= w and i[:len(w) - 1] == w[:-1]
    if op == '==':
        return i == w
    if op == '>=':
        return i >= w
    return i < w

def find_conflicts(needs):
    wanted = {}
    for deps in needs.values():
        for dep, version in deps.items():
            wanted.setdefault(dep, set()).add(version)
    return {dep: sorted(v) for dep, v in wanted.items() if len(v) > 1}
